    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    max_rem = np.max(remaining[valid])
    if max_rem == 0:
        scores = np.zeros_like(remaining, dtype=float)
    else:
        scores = -np.exp(remaining / max_rem)
    return np.where(valid, scores, -np.inf)
